const http = require('http');

const server = http.createServer((req, res) => {
  // --- THE REQUEST (req) ---
  console.log("Method:", req.method);
  console.log("Headers:", req.headers['user-agent']);

  // To read POST body data in raw Node, you must use Streams!
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    console.log("Body Received:", body);

    // --- THE RESPONSE (res) ---
    // 1. Send the envelope (Headers + Status)
    res.writeHead(200, { 'Content-Type': 'text/plain' });

    // 2. Put the letter inside (Body)
    res.write('Message received loud and clear.');

    // 3. Mail it! (Hang up the connection)
    res.end();
  });
});

console.log("Express hides all this stream logic behind 'req.body'!");
